---升级按钮点击回调
function CardProgressionEquipmentStarUpDialog:BtnUpgradeOnClickHandler()
    local equipDojo = self:GetEquipDojo()
    local cost = self:GetUpgradeCost()
    if not GoodsUtils.CheckConsumeDataCondition(cost, 10) then
        return
    end

    for i, v in ipairs(cost) do
        local num = GoodsUtils.GetThingNo(v.goodsId)
        if num < checkInt(v.goodsNum) then
            GameUtils.Toast(localize("道具不足"))
            return
        end
        v.num = -(v.goodsNum)
    end
    CardProgressionMgr:RequestOverseaEquipmentStarUp({playerEquipmentId = equipDojo.id}, cost)
    self:CloseDialog()
end

---快速升级按钮点击回调
function CardProgressionEquipmentStarUpDialog:BtnQuickUpgradeOnClickHandler()
    local equipDojo = self:GetEquipDojo()
    local canUpgrade, consume, star, level = EquipUtils.CalculateQuickUpgradeConsume(equipDojo)
    if not canUpgrade then
        -- GameUtils.Toast(localize("道具不足"))
        local cost = self:GetUpgradeCost()
        if not GoodsUtils.CheckConsumeDataCondition(cost, 10) then
            return
        end
        return
    end
    local tips = nil
    if level == 0 then
        tips = localize("快速升级将消耗以下材料，将装备提升至<color=#e71f55>_num1_星</color>，是否确认？", {_num1_ = star})
    else
        tips = localize("快速升级将消耗以下材料，将装备提升至<color=#e71f55>_num1_星+_num2_</color>，是否确认？", {_num1_ = star, _num2_ = level})
    end
    for _, v in ipairs(consume) do
        v.forceText = v.goodsNum
        v.num = -v.goodsNum
    end
    GameUtils.SecondConfirm(tips, function()
        CardProgressionMgr:RequestOverseaEquipmentQuickUpgrade({playerEquipmentId = equipDojo.id, targetLevel = level, targetStar = star}, consume)
        self:CloseDialog()
    end, nil, nil, 4, consume, true)
end

