---刷新装备道具
function CardProgressionEquipmentStarUpDialog:RefreshEquipmentGoods()
    local equipDojo = clone(self:GetEquipDojo())
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local goodsVo = goodsConfMgr:GetGoodsVoById(equipDojo.equipmentId)
    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.BeforeGoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:Reload({dojo = equipDojo, goodsId = equipDojo.equipmentId, isShowNo = false})
    end

    equipDojo.star = checkInt(equipDojo.star) + 1
    equipDojo.level = 0
    ---@type GoodNodeMB
    local mbEnv2 = CfUtils.GetLuaScr(self.AfterGoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv2 then
        mbEnv2:Reload({dojo = equipDojo, goodsId = equipDojo.equipmentId, isShowNo = false})
    end

    CfUtils.FillText(self.TxtEquipName, goodsVo.name)
end

---刷新属性
function CardProgressionEquipmentStarUpDialog:RefreshAttrs()
    local equipDojo = self:GetEquipDojo()
    local node = self.ATKNumericalValue:Find("SubAttrNode1")
    self:RefreshAttrNodeState(equipDojo, node)
end

---刷新按钮
function CardProgressionEquipmentStarUpDialog:RefreshBtn()
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComponent.playerDojo
    local equipLevelUpTimes = checkInt(playerDojo.equipLevelUpTimes)
    local limit = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentQuickUpgradeLimit))
    if equipLevelUpTimes >= limit then
        CfUtils.SetActive(self.Quick, true)
        CfUtils.SetActive(self.QuickCommonBtnConsumePop, false)
    else
        CfUtils.SetActive(self.Quick, false)
    end
end

---刷新属性node状态
---@param equipDojo table
---@param node  UnityEngine.Transform
---@param index integer 位置
function CardProgressionEquipmentStarUpDialog:RefreshAttrNodeState(equipDojo, node)
    local index = checkInt(equipDojo.star) + 1
    local key = string.format("attr%sId", index)
    local attrAdditionId = checkNumber(equipDojo[key])
    if checkNumber(attrAdditionId) == 0 then return end

    CfUtils.SetActive(self.LockNode, true)
    key = string.format("attr%sNum", index)
    local attrNum = equipDojo[key]
    local qKay = string.format("attr%sQuality", index)
    local attrQuality = checkInt(equipDojo[qKay])
    local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(attrAdditionId) or {}
    self.AttrNameText.text = attrAdditionVo.attrAdditionName
    self.AttrNumText.text = attribute_format(attrAdditionVo.isConversion, attrNum)
    EquipUtils.SwitchSubAttrColorByQuality(self.ImgBgRare, attrQuality)
    local percent = EquipUtils.GetSubAttrPercent(equipDojo.equipmentId, attrAdditionId, attrNum)
    self.Slider.value = percent
    CfUtils.SetUISwitchImage(self.ImgPointRare, attrQuality)
    CfUtils.FillText(self.TxtSerialNumber, index)
end 

---刷新升级消耗
function CardProgressionEquipmentStarUpDialog:RefreshUpgradeCost()
    local cost = self:GetUpgradeCost()
    
    -- 处理金币消耗
    local goldNum = nil
    for i, v in ipairs(cost) do
        if checkInt(v.goodsId) == Constants.Currency.GoldId then
            goldNum = v.goodsNum
            table.remove(cost, i)
            break
        end 
    end
    if goldNum then
        CfUtils.SetActive(self.CommonBtnConsumePop, true)
        CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, Constants.Currency.GoldId, goldNum, false, false)
    else
        CfUtils.SetActive(self.CommonBtnConsumePop, false)
    end
    
    CfUtils.RefreshCommonGoodsListLight(self.CommonGoodsList, cost, false, false, true, true, true)
end

---关闭界面
function CardProgressionEquipmentStarUpDialog:CloseDialog()
    UIModule.CloseDialog(self.controller)
end

---获取EquipDojo
function CardProgressionEquipmentStarUpDialog:GetEquipDojo()
    return self._equipDojo
end

---获取升级消耗
function CardProgressionEquipmentStarUpDialog:GetUpgradeCost()
    local equipDojo = self:GetEquipDojo()
    local goodsVo = goodsConfMgr:GetGoodsVoById(equipDojo.equipmentId)
    local params = {
        quality = goodsVo.quality,
        star    = equipDojo.star + 1,
        level   = 0
    }
    local equipmentCNRVo = EquipUtils.GetEquipmentCNRVo(params)
    return parse_rewards(equipmentCNRVo.upstarItem, equipmentCNRVo.upstarNum)
    
end
